// This file is automatically generated. Do not edit it directly.
import { createClient } from "@supabase/supabase-js";
import type { Database } from "./types";
import { resolveSupabaseConfig } from "./config";
import { isDemoMode } from "@/lib/demo/mode";

// Without VITE_SUPABASE_* a production build throws, and the dev server and server rendering use
// an address that resolves nowhere: nothing ever reaches another person's project.
const {
  url: SUPABASE_URL,
  key: SUPABASE_PUBLISHABLE_KEY,
  configured,
} = resolveSupabaseConfig({
  url: import.meta.env["VITE_SUPABASE_URL"],
  key: import.meta.env["VITE_SUPABASE_PUBLISHABLE_KEY"],
  hostname: typeof window === "undefined" ? undefined : window.location.hostname,
  dev: import.meta.env.DEV,
});

if (!configured && typeof window !== "undefined") {
  console.warn(
    "[my-wealth-view] VITE_SUPABASE_URL / VITE_SUPABASE_PUBLISHABLE_KEY not set: only /demo works. " +
      "Set them in .env (see .env.example) to use your own project.",
  );
}

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

const realClient = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
  },
});

// Supabase signs in from a password-recovery email link with the PASSWORD_RECOVERY event. Listening
// from load, before the client reads the link, means a page that mounts later still knows.
let recoveryLink = false;
realClient.auth.onAuthStateChange((event) => {
  if (event === "PASSWORD_RECOVERY") recoveryLink = true;
});
/** True once this tab was signed in by a password-recovery email link. */
export const openedFromRecoveryLink = () => recoveryLink;

// The demo's fake client (and its generated data) is a separate chunk, loaded only when the demo
// is entered or a demo tab is reloaded, so real visits don't download it.
let demoModule: typeof import("@/lib/demo/fake-client") | null = null;
export async function loadDemoClient(): Promise<void> {
  demoModule ??= await import("@/lib/demo/fake-client");
}

// Every screen uses this one object. In demo mode each call is answered by the in-memory fake
// instead, so the demo cannot reach the real database, bank functions or login.
export const supabase = new Proxy(realClient, {
  get(_target, prop) {
    if (isDemoMode() && !demoModule) {
      // Never fall back to the real client in the demo: /demo and the root route load it first.
      throw new Error("The demo is still loading.");
    }
    const target = isDemoMode() ? demoModule!.getDemoClient() : realClient;
    const value: unknown = Reflect.get(target, prop);
    return typeof value === "function" ? value.bind(target) : value;
  },
});

/** Called when entering the demo: stop a stored real login from refreshing its token in the background. */
export function pauseRealClient(): void {
  void realClient.auth.stopAutoRefresh();
}
